<template>


<button class="btn btn-primary"
data-bs-toggle="modal"
data-bs-target="#budget-edit-modal"
@click="fillModal()"
>Edit</button>




                     <div class="modal fade mymodal" id="budget-edit-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="staticBackdropLabel" aria-hidden="true">
  <div class="modal-dialog modal-fullscreen">
    <div class="modal-content" >
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="staticBackdropLabel"> USERS BASED ON SERVICES </h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" id="close" ></button>
      </div>

<div class="modal-body" >

        <div class = "row">
       <div class="col-md-4">
       SERVICES LIST
  <ol class="list-group list-group-numbered " style="max-height: 670px; overflow-y: auto;">
    <div v-if="loading" class="text-center py-5">
      <div class="spinner-border text-info" role="status">
        <span class="visually-hidden">Loading...</span>
      </div>
      <p class="mt-2">Loading data...</p>
    </div>
<!-- in the master services sidebar list -->
<li v-else class="list-group-item list-group-item-action d-flex justify-content-between align-items-center"
  :class="selectedService === service ? 'bg-primary text-white' : ''"
  style="cursor: pointer;"
  v-for="service in services"
  @click="selectService(service)">
   <div class="fw-bold">{{ service.name }}</div>
      {{service.type}}
</li>  </ol>
        </div>
        <div class="col-md-8">
             USERS LIST
             <span v-if="loadingUsers" v-html="waitIndicator()"></span>

                 <div v-else  class="row layout-top-spacing" style="max-height: 67vh; overflow-y: auto;">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                        <v-client-table :data="userDirectory" :columns="userColumns" :options="table_option" >
                        </v-client-table>
                    </div>
                </div>
            </div>
        </div>

        </div>

    </div>
    

      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-danger " data-bs-dismiss="modal">Close</button>
      </div>
    </div>
  </div>

</div>


</template>


<script setup>
    import { onMounted, ref, inject, watch, computed } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    useMeta({ title: 'Budget Editing' });
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });




    const table_option = ref({
    perPage: 10,
    perPageValues: [10, 20, 50],
    skin: 'table table-hover table-striped',
    columnsClasses: { actions: 'actions text-center' },
    sortable: ['title', 'subcontracted_to', 'quantity', 'rate', 'cost', 'balance'],
    sortIcon: {
        base: 'sort-icon-none',
        up: 'sort-icon-asc',
        down: 'sort-icon-desc',
    },
    pagination: { nav: 'scroll', chunk: 5 },
    texts: {
        count: 'Showing {from} to {to} of {count}',
        filter: '',
        filterPlaceholder: 'Search...',
        limit: 'Results:',
    },
    resizableColumns: false,
});


    const openModalOnModal = inject('openModalOnModal')


const userColumns = ref(['Sno', 'name','email','phone']);

const user_permissions = JSON.parse(localStorage.getItem('user')).permissions
const props = defineProps({
    BudgetId: String,
});

const loading = ref(false)

const showError = inject('showError')
const showMessage = inject('showMessage')
const waitIndicator = inject('waitIndicator')

    const units = ref([])
    const unit = ref('')


    const section_length = ref('')
    const budget_descriptions = ref('')
    const budget_name = ref('')
    const boqLines = ref([])
    
    const loadingData = ref(false)
const fillModal = async () => {
  loadingData.value = true
    if (!budgetData.value || !boqLines.value.length) {
        await Promise.all([
            getBudgetData(),
        ])    }
          loadingData.value = false
    section_length.value = budgetData.value.section_length
    budget_descriptions.value = budgetData.value.budget_descriptions
    unit.value =   units.value.find(unt => unt.name === budgetData.value.unit)
    budget_name.value = budgetData.value.budget

    selectedBoqLines.value = boqLines.value.filter(line =>
        budgetData.value.boq_lines?.some(selected =>
            selected.id === line.id ||
            selected.boq_line_id === line.id
        )
    )
}

const selectedBoqLines = ref([])


const selectService = (service)=>{
  selectedService.value = service
  getUserDirectory()
}
const selectedService = ref('')

const budgetData = ref('')
const getBudgetData = async()=>{
  loading.value = true
  try{
    const response = await axiosInstance.get(`budget-data?budget_id=47`)
    budgetData.value = response.data
  }catch(error){
    showError(error.message)
    console.log(error)
  }finally{
    loading.value = false
  }
}


const userDirectory = ref([])
const loadingUsers = ref(false)
const getUserDirectory = async () => {
  loadingUsers.value = true
    const response = await axiosInstance.get(`/user-directory/users?service_id=${selectedService.value.id}`);

    userDirectory.value = response.data.data.users.map((item,index) => ({
        Sno : index+ 1,
        uu_id: item.uuid,
        name: item.username,
        phone: item.phone_number,
        email: item.email
    }));

    loadingUsers.value = false

};

const services = ref([])
const getServices = async () => {
  loading.value = true
    const response = await axiosInstance.get('/user-directory/services');
loading.value = false
    services.value = response.data.data.services
};


    onMounted(async() => {
       getServices()
    });
</script>





